import {renderVersionSelectOptions} from '../poem-version-selection.js';
import {applicationState} from '../application-state.js';
import {STORAGE_KEY,LIBRARY_KEY,WRITERS_LIST,escapeHtml as h,tagsFromText,latestVersion,resolveSelection,countLines,calendarText,upcomingNotices,readEditorLibrary,seedData} from './model.js';
import {downloadFile,safeName,buildDocx,printDocument} from './document-export.js';
import {DEFAULT_AI_STATEMENT,plicaExportFields} from '../plica-policy.js';
import {createLibrary} from './library-view.js';
import {documentPreview} from './document-preview.js';
import {coverOptions,coverWarnings} from './cover-policy.js';
import {createReminderNotifications} from './reminder-notifications.js';
import {tagCatalog,createTag,updateTagEverywhere,tagColor,setTagColor,tagMarkup,ensureTagColors} from './tag-library.js';
function load(){try{return JSON.parse(localStorage.getItem(STORAGE_KEY))||seedData();}catch{return seedData();}}
applicationState.prototype={data:load(),view:'library',contestId:'manini',query:'',tags:[],tagMode:'all',checked:[],draft:null,preview:'poem',toastTimer:null,editorReady:false,pendingOpen:null,plicaDraft:null};
const state=applicationState.prototype;
const requestedView=new URLSearchParams(location.search).get('view');if(['editor','library','contests','reminders'].includes(requestedView))state.view=requestedView;
ensureTagColors(state.data,allPoems());
state.library={tab:'poems',poemId:'',versionId:'latest',settings:{},pending:{},confirmation:null};
const main=document.querySelector('#main'),modal=document.querySelector('#modal');
const sidebarToggle=document.querySelector('#sidebar-toggle');
function setSidebarCollapsed(collapsed){document.documentElement.classList.toggle('sidebar-collapsed',collapsed);sidebarToggle.setAttribute('aria-expanded',String(!collapsed));const label=collapsed?'Expandir barra lateral':'Contraer barra lateral';sidebarToggle.setAttribute('aria-label',label);sidebarToggle.title=label;try{localStorage.setItem('escandador.workshopSidebar.v1',collapsed?'collapsed':'expanded');}catch{}}
let savedSidebar=false;try{savedSidebar=localStorage.getItem('escandador.workshopSidebar.v1')==='collapsed';}catch{}setSidebarCollapsed(savedSidebar);
sidebarToggle.addEventListener('click',()=>setSidebarCollapsed(!document.documentElement.classList.contains('sidebar-collapsed')));
function libraryCommand(command){return new Promise((resolve,reject)=>{
  if(!state.editorReady){reject(Error('El Taller está cargando. Probá nuevamente en un momento.'));return;}
  const requestId=crypto.randomUUID();const timeout=setTimeout(()=>{delete state.library.pending[requestId];reject(Error('No se pudo completar la acción de Biblioteca.'));},10000);
  state.library.pending[requestId]={resolve,reject,timeout};document.querySelector('#workshop-editor').contentWindow.postMessage({type:'workshop:library-command',requestId,command},location.origin);
});}
const library=createLibrary({state,allPoems,persist,showDialog,toast,command:libraryCommand,openEditor,render});
const reminderNotifications=createReminderNotifications({getContests:()=>state.data.contests,onOpen:id=>{window.focus();state.view=id?'detail':'reminders';if(id)state.contestId=id;render();},onStatus:()=>{if(state.view==='reminders')renderReminders();}});
reminderNotifications.start();
const statusNames={interested:'Me interesa',preparing:'Preparando',sent:'Enviado',closed:'Cerrado'};
const icon='<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M12 3v18M3 12h18"/></svg>';
const dateLabel=date=>date?new Intl.DateTimeFormat('es-UY',{day:'numeric',month:'long',year:'numeric'}).format(new Date(date+'T12:00:00')):'Sin fecha exacta';
const safeLink=value=>{try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?h(u.href):'';}catch{return '';}};
const tagsMarkup=tags=>tags.map(t=>tagMarkup(state.data,t)).join('');
function allPoems(){const local=readEditorLibrary(localStorage),linked=new Set(state.data.poems.map(p=>p.linkedLocalId).filter(Boolean));return [...state.data.poems.flatMap(p=>{if(!p.linkedLocalId)return [p];const actual=local.find(l=>l.id===p.linkedLocalId);return actual?[{...actual,id:p.id,sourceKey:p.linkedLocalId.slice(6),tags:p.tags}]:[];}),...local.filter(p=>!linked.has(p.id)).map(p=>({...p,sourceKey:p.id.slice(6),tags:state.data.localTags[p.id]||[]}))];}
function currentContest(){return state.data.contests.find(c=>c.id===state.contestId);}
function selectedEntries(c){return resolveSelection(allPoems(),c.selections).filter(e=>e.poem&&e.version);}
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state.data));reminderNotifications.check();return true;}catch{toast('No se pudo guardar: el almacenamiento del navegador está lleno.');return false;}}
function toast(message){clearTimeout(state.toastTimer);const e=document.querySelector('#toast');e.textContent=message;e.style.display='block';state.toastTimer=setTimeout(()=>e.style.display='none',5000);}
function showDialog(title,content,wide=false){modal.style.width=wide?'min(820px, calc(100vw - 32px))':'';modal.innerHTML=`<div class="dialog-head"><div><p class="eyebrow">MESA DE POESÍA</p><h2 id="dialog-title">${h(title)}</h2></div><button data-action="close" aria-label="Cerrar">×</button></div>${content}`;if(!modal.open)modal.showModal();}
function heading(eyebrow,title,subtitle,buttons=''){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="actions">${buttons}</div></div>`;}
function applyEditorTheme(){document.documentElement.classList.toggle('working-poem',!!state.editorTheme);document.documentElement.style.setProperty('--working-poem-color',state.editorTheme||'#923e36');}
window.addEventListener('poem-color-intensity',event=>{libraryCommand({action:'color-intensity',value:event.detail}).catch(()=>{});});
function render(){
  applyEditorTheme();
  document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===(['detail','export'].includes(state.view)?'contests':state.view)));
  document.querySelector('#poem-count').textContent=allPoems().length;
  document.querySelector('#contest-count').textContent=state.data.contests.length;
  document.querySelector('#reminder-count').textContent=upcomingNotices(state.data.contests).length;
  const host=document.querySelector('#editor-host');host.hidden=state.view!=='editor';
  if(!host.hidden){main.innerHTML=heading('MI TALLER','Escandidor.','Trabajá con tus textos, configuración métrica, rimas y definiciones.','<button data-view="library">Abrir Biblioteca</button>');document.querySelector('#workshop-editor').contentWindow.postMessage({type:'workshop:view',view:'editor'},location.origin);return;}
  if(state.view==='library')renderLibrary();else if(state.view==='contests')renderContests();else if(state.view==='reminders')renderReminders();else if(state.view==='export')renderExport();else renderDetail();
}
function renderLibrary(){main.innerHTML=library.renderHtml(heading);}
function contestCard(c){const date=c.deadline?new Date(c.deadline+'T12:00:00'):null;return `<article class="contest-card"><div class="date-tile"><strong>${date?date.getDate():'—'}</strong><span>${date?date.toLocaleDateString('es',{month:'short'}).toUpperCase():'CIERRE'}</span></div><div><h3>${h(c.name)}</h3><div class="meta"><span>${h(c.country||'País sin indicar')}</span><span>${h(c.delivery)}</span><span>${dateLabel(c.deadline)}</span></div><div class="tag-row"><span class="tag ${c.status==='sent'?'blue':''}">${statusNames[c.status]}</span><span class="tag gray">${c.selections.length} poemas asociados</span>${c.demo?'<span class="tag gray">Ficha de ejemplo</span>':`<span class="tag ${c.reviewed?'':'rose'}">${c.reviewed?'Datos revisados':'Revisar datos'}</span>`}</div></div><div class="actions"><button data-action="open-contest" data-id="${h(c.id)}">Abrir concurso →</button></div></article>`;}
function renderContests(){main.innerHTML=heading('OPORTUNIDADES PARA TU ESCRITURA','Cada poema, una posibilidad.','Encontrá un concurso en Escritores.org, pegá su enlace y prepará tu participación.',`<button class="primary" data-action="import">${icon} Agregar desde URL</button>`)+`<div class="notice"><div><strong>De la convocatoria a tu taller.</strong> Extraemos los datos disponibles; vos completás y revisás los requisitos.</div><a href="${WRITERS_LIST}" target="_blank" rel="noopener noreferrer">Ver concursos ↗</a></div><div class="section-title"><h2>Mis concursos</h2><span>${state.data.contests.length} guardados · ordenados por cierre</span></div><div class="contest-list">${[...state.data.contests].sort((a,b)=>(a.deadline||'9999').localeCompare(b.deadline||'9999')).map(contestCard).join('')||'<div class="empty">Pegá la URL de tu primer concurso.</div>'}</div>`;}
function renderDetail(){
  const c=currentContest();if(!c){state.view='contests';render();return;}
  const poems=allPoems(),entries=selectedEntries(c),count=entries.reduce((n,e)=>n+countLines(e.version.poemText).verses,0);
  main.innerHTML=`<button class="back" data-view="contests">← Mis concursos</button>`+heading(h(c.country||'CONCURSO'),h(c.name),'Elegí tus poemas y prepará una entrega a tu medida.',`<button data-action="edit-contest">Editar datos</button><button data-action="toggle-agenda" data-id="${h(c.id)}">${c.agendaEnabled===false?'Agregar a la agenda':'Quitar de la agenda'}</button><button data-action="delete-contest" data-id="${h(c.id)}">Eliminar concurso</button><button class="primary" data-action="prepare">Preparar entrega →</button>`)+`${c.demo?'<div class="notice warm">Ficha de ejemplo con requisitos de referencia. Revisá las bases antes de participar.</div>':!c.reviewed?'<div class="notice warm">Los datos extraídos necesitan revisión. Comprobá especialmente formatos, fechas y condiciones de participación.</div>':''}<div class="detail-layout"><div><section class="panel"><div class="row"><h2>La convocatoria</h2><span class="tag">${statusNames[c.status]}</span></div><dl class="fact-grid"><div><dt>Organiza</dt><dd>${h(c.organizer||'Sin indicar')}</dd></div><div><dt>Medio de entrega</dt><dd>${h(c.delivery)}</dd></div><div><dt>Cierre de recepción</dt><dd>${dateLabel(c.deadline)}<br><span class="small muted">${h(c.deadlineTime||'Hora no indicada')} ${h(c.timezone||'')}</span></dd></div><div><dt>Resultados</dt><dd>${c.resultsDate?dateLabel(c.resultsDate):'Sin día exacto'}<br><span class="small muted">${h(c.resultsNote||'Fecha del fallo no encontrada.')}</span></dd></div></dl><p class="small muted" style="white-space:pre-line">${h(c.rules)}</p><div class="actions" style="margin-top:18px">${safeLink(c.sourceUrl)?`<a class="small" href="${safeLink(c.sourceUrl)}" target="_blank" rel="noopener noreferrer">Convocatoria en Escritores.org ↗</a>`:''}${safeLink(c.originalUrl)?`<a class="small" href="${safeLink(c.originalUrl)}" target="_blank" rel="noopener noreferrer">Organizador / bases originales ↗</a>`:''}<button data-action="refresh" ${c.sourceUrl?'':'disabled'}>Volver a consultar</button></div></section><section class="panel"><div class="row"><h2>Poemas para este concurso</h2><span class="small muted">${entries.length} poemas · ${count} versos</span></div><p class="small muted">La selección sigue la última versión guardada. Podés fijar otra versión si querés.</p>${poems.map(p=>{const selection=c.selections.find(s=>s.poemId===p.id),v=latestVersion(p);return `<div class="selection-row"><button data-action="edit-tags" data-id="${h(p.id)}">Agregar etiquetas</button><button data-action="open-contest-poem" data-id="${h(p.id)}" aria-label="Abrir ${h(p.title)} en Escandidor">Abrir en Escandidor ↗</button><input type="checkbox" aria-label="Asociar ${h(p.title)}" data-associate="${h(p.id)}" ${selection?'checked':''}><div><h3>${h(p.title)}</h3><div class="tag-row">${tagsMarkup(p.tags)}</div>${selection?`<span class="live-label">${selection.versionId==='latest'?'↻ Sigue la última versión · '+h(v.label||'Actual'):'Versión fija'}</span>`:''}</div><select aria-label="Versión de ${h(p.title)}" data-version-poem="${h(p.id)}" ${selection?'':'disabled'}><option value="latest" ${selection?.versionId==='latest'?'selected':''}>Última versión · automática</option>${renderVersionSelectOptions(p.versions,selection?.versionId,v=>`${v.label||'Versión '+v.versionNumber} · fija`)}</select></div>`;}).join('')}</section>${c.snapshots.length?`<section class="panel"><h2>Historial de entregas</h2>${c.snapshots.map((s,i)=>`<div class="timeline-item"><strong>Entrega ${i+1} · ${new Date(s.sentAt).toLocaleDateString('es-UY')}</strong><p>${s.entries.length} poemas · copia conservada de las versiones y el formato</p><button data-action="snapshot" data-index="${i}">Consultar copia entregada</button></div>`).join('')}</section>`:''}</div><aside><section class="panel"><p class="aside-label">TU PARTICIPACIÓN</p><select id="contest-status" class="status-select" aria-label="Estado del concurso">${Object.entries(statusNames).map(([v,label])=>`<option value="${v}" ${c.status===v?'selected':''}>${label}</option>`).join('')}</select><p class="hint">Marcar como enviado conserva la última preparación descargada, o la selección actual si todavía no exportaste.</p><button data-action="sent" style="width:100%;margin-top:15px">Marcar entrega como enviada</button></section><section class="panel"><p class="aside-label">RECORDATORIOS</p><p class="deadline">${c.deadline?dateLabel(c.deadline).replace(/ de \d{4}/,''):'Sin fecha'}</p><p class="small muted">${c.agendaEnabled===false?'Fuera de la agenda: los avisos de este concurso están pausados.':'En la agenda: avisos de cierre y resultados activos.'}</p><div class="actions">${[14,7,2].map(n=>`<label class="check"><input type="checkbox" data-reminder="${n}" ${(c.reminders||[]).includes(n)?'checked':''}>${n} días</label>`).join('')}</div><button data-action="calendar" style="width:100%;margin-top:17px" ${c.deadline?'':'disabled'}>Descargar evento .ics</button><p class="hint">Opción manual: importalo en Google Calendar desde Configuración → Importar y exportar. Activá los avisos del navegador desde Recordatorios.</p></section><section class="panel"><p class="aside-label">EL FALLO</p>${c.resultsUrl?`<span class="tag">${c.demo?'Resultado de ejemplo':'Publicación confirmada'}</span><p class="hint">${c.demo?'Este ejemplo muestra el aviso; no representa un resultado real.':'Enlace confirmado por vos.'}</p><a class="small" href="${safeLink(c.resultsUrl)}" target="_blank" rel="noopener noreferrer">Ver publicación ↗</a>`:`<p class="small muted">La fecha prevista no confirma la publicación.</p>`}<button data-action="results" style="width:100%;margin-top:14px">Registrar enlace de resultados</button>${c.resultsDate?'<button data-action="results-calendar" class="quiet" style="width:100%;margin-top:8px">Recordar fecha prevista</button>':''}</section></aside></div>`;
}
function renderReminders(){
  const notices=upcomingNotices(state.data.contests),notificationStatus=reminderNotifications.status();
  main.innerHTML=heading('SIN PERDER DE VISTA LAS FECHAS','Lo próximo en tu taller.','Cierres, fechas previstas del fallo y publicaciones confirmadas.')+`<section class="panel notification-settings"><div><h2>Avisos en este navegador</h2><p class="muted">${h(notificationStatus.message)}</p><p class="hint">Con el taller abierto, recibís avisos aunque estés en otra pestaña. Los cierres respetan los días elegidos en cada concurso; también te avisamos cuando registres un enlace de resultados. Los concursos de ejemplo no envían avisos.</p></div><button class="${notificationStatus.enabled?'quiet':'primary'}" data-action="${notificationStatus.enabled?'disable':'enable'}-notifications" ${notificationStatus.available?'':'disabled'}>${notificationStatus.enabled?'Desactivar avisos':'Activar avisos'}</button></section><div class="notice"><div><strong>Avisos claros.</strong> Una fecha de fallo prevista y unos resultados publicados son eventos distintos.</div></div><section class="panel"><h2>Tu agenda</h2>${notices.map(n=>`<article class="reminder-row"><span class="reminder-icon" aria-hidden="true">${n.kind==='published'?'✓':n.kind==='results'?'◷':'⌁'}</span><div><div class="tag-row"><span class="tag ${n.kind==='expired'?'rose':''}">${h(n.label)}</span>${n.contest.demo?'<span class="tag gray">Ejemplo</span>':''}</div><h3 style="margin-top:10px">${h(n.contest.name)}</h3><p class="small muted">${h(n.detail)}</p></div><div class="actions"><button data-action="toggle-agenda" data-id="${h(n.contest.id)}" class="quiet">Quitar de la agenda</button>${n.kind!=='published'?`<button data-action="${n.kind==='results'?'results-calendar':'calendar'}" data-id="${h(n.contest.id)}" class="quiet">Descargar evento .ics</button>`:''}<button data-action="open-contest" data-id="${h(n.contest.id)}">${n.kind==='published'?'Consultar resultados':'Abrir concurso'} →</button></div></article>`).join('')||'<div class="empty">No hay avisos próximos. Los recordatorios aparecerán según las fechas que guardes.</div>'}</section>${state.data.contests.some(c=>c.agendaEnabled===false)?`<section class="panel"><h2>Fuera de la agenda</h2><p class="hint">Conservás estos concursos, sus poemas y sus entregas. No generan avisos.</p>${state.data.contests.filter(c=>c.agendaEnabled===false).map(c=>`<article class="reminder-row"><div><h3>${h(c.name)}</h3></div><div class="actions"><button data-action="toggle-agenda" data-id="${h(c.id)}">Agregar a la agenda</button><button data-action="open-contest" data-id="${h(c.id)}">Abrir concurso</button></div></article>`).join('')}</section>`:''}<section class="panel"><h2>También fuera del taller</h2><p class="muted">Si preferís tu calendario, descargá el evento .ics e importalo manualmente en Google Calendar desde Configuración → Importar y exportar. Esto crea un evento; también podés crear una tarea directamente en Google Calendar.</p><span class="tag gray">Los avisos del navegador requieren que el taller esté abierto</span></section>`;
}
function verseCountForContest(text,c){return c.verseCounting==='includes-title-and-blanks'?String(text).trimEnd().split('\n').length+1:countLines(text).verses;}
function renderExport(){
  const c=currentContest(),entries=selectedEntries(c),p=c.profile,total=entries.reduce((n,e)=>n+countLines(e.version.poemText).verses,0),quotes=entries.reduce((n,e)=>n+countLines(e.version.poemText).quotes,0);
  const checks=[...(c.minPoemVerses?[{ok:entries.every(e=>verseCountForContest(e.version.poemText,c)>=c.minPoemVerses),text:`Mínimo ${c.minPoemVerses} versos por poema`}]:[]),{ok:!!entries.length,text:`${entries.length} poemas · ${total} versos del cuerpo · ${quotes} líneas de cita`},{ok:!c.maxPoems||entries.length<=c.maxPoems,text:c.maxPoems?`Máximo ${c.maxPoems} poemas`:'Cantidad de poemas: verificar las bases'},{ok:!c.maxVerses||entries.every(e=>verseCountForContest(e.version.poemText,c)<=c.maxVerses),text:c.maxVerses?`Máximo ${c.maxVerses} versos por poema`:'Versos por poema: sin límite configurado'},{ok:(!c.minTotal||total>=c.minTotal)&&(!c.maxTotal||total<=c.maxTotal),text:c.minTotal||c.maxTotal?`Conjunto: ${c.minTotal||0}–${c.maxTotal||'sin máximo'} versos`:'Extensión del conjunto: verificar las bases'}];
  main.innerHTML=`<button class="back" data-action="open-contest" data-id="${h(c.id)}">← ${h(c.name)}</button>`+heading('PREPARAR ENTREGA','Tu poema, listo para salir.','El formato cambia para este concurso; el texto original se conserva.',`<button data-action="plica">${c.plicaRequired===false?'Datos de autoría':'Preparar plica'}</button><button data-action="docx" ${entries.length?'':'disabled'}>Descargar DOCX</button><button class="primary" data-action="pdf" ${entries.length?'':'disabled'}>Imprimir / guardar PDF ↗</button>`)+`<div class="export-layout"><aside class="export-config"><section class="panel"><h2>Formato del concurso</h2><div class="form-grid"><label class="full">Tipografía<select data-profile="font">${['Times New Roman','Arial','Calibri','Georgia'].map(f=>`<option ${p.font===f?'selected':''}>${f}</option>`).join('')}</select></label><label>Tamaño (pt)<input type="number" min="8" max="24" value="${p.size}" data-profile="size"></label><label>Interlineado<select data-profile="lineSpacing">${[1,1.5,2].map(n=>`<option value="${n}" ${p.lineSpacing===n?'selected':''}>${n===2?'Doble':n}</option>`).join('')}</select></label><label>Hoja<select data-profile="paper"><option value="A4" ${p.paper==='A4'?'selected':''}>A4</option><option value="Letter" ${p.paper==='Letter'?'selected':''}>Carta</option></select></label><label>Márgenes (cm)<input type="number" min="1" max="5" step="0.1" value="${p.margin}" data-profile="margin"></label><label class="check full"><input type="checkbox" data-profile="newPage" ${p.newPage?'checked':''}>Un poema por página</label><label class="check full"><input type="checkbox" data-profile="numbered" ${p.numbered?'checked':''}>Numerar páginas (DOCX)</label></div><p class="hint">En PDF usá «Guardar como PDF» del navegador. La numeración depende de sus opciones de impresión.</p></section><section class="panel"><h2>Portada y primera página</h2><div class="stack"><label class="check"><input type="checkbox" data-profile="cover" ${p.cover?'checked':''}>Incluir portada separada</label><label>Título del conjunto<input data-profile="workTitle" value="${h(p.workTitle)}"></label><label>Seudónimo<input data-profile="pseudonym" value="${h(p.pseudonym)}"></label><p class="hint">Si las bases prohíben la firma, el seudónimo se reserva para la plica y no aparece en la obra.</p>${p.cover?`<label class="check"><input type="checkbox" data-profile="coverTitle" ${coverOptions(c).title?'checked':''}>Mostrar título</label><label class="check"><input type="checkbox" data-profile="coverPseudonym" ${coverOptions(c).pseudonym?'checked':''}>Mostrar seudónimo si las bases lo permiten</label><label class="check"><input type="checkbox" data-profile="coverContestName" ${coverOptions(c).contestName?'checked':''}>Mostrar nombre del concurso</label><label class="check"><input type="checkbox" data-profile="coverVerses" ${coverOptions(c).verses?'checked':''}>Mostrar número de versos</label><label>Lema (opcional)<input data-profile="coverMotto" maxlength="600" value="${h(p.coverMotto||'')}"></label><label>Declaración de IA en la primera página<textarea data-profile="coverStatement" rows="4" maxlength="6000" placeholder="Copiá el texto que piden las bases y verificá que describa tu caso.">${h(p.coverStatement||'')}</textarea></label><label>Alineación<select data-profile="coverAlignment"><option value="center" ${coverOptions(c).alignment==='center'?'selected':''}>Centrada</option><option value="left" ${coverOptions(c).alignment==='left'?'selected':''}>A la izquierda</option></select></label><label>Posición<select data-profile="coverPosition"><option value="top" ${coverOptions(c).position==='top'?'selected':''}>Arriba</option><option value="middle" ${coverOptions(c).position==='middle'?'selected':''}>Con espacio superior</option></select></label><p class="hint">Marcá solo lo que piden las bases. El texto de la declaración es editable y no se completa ni firma automáticamente.</p>`:''}</div></section><section class="panel"><h2>Epígrafes y citas</h2><label class="check"><input type="checkbox" data-profile="quoteItalic" ${p.quoteItalic?'checked':''}>Cita en cursiva</label><p class="hint">Las líneas con &gt; se exportan sin el marcador, con sangría y separación. Se conserva la fuente y el tamaño del concurso.</p></section></aside><div><div class="preview-tabs"><button data-action="preview-poem" class="${state.preview==='poem'?'active':''}">Poemas</button><button data-action="preview-cover" class="${state.preview==='cover'?'active':''}" ${p.cover?'':'disabled'}>Portada</button><span class="small muted" style="margin-left:auto">Vista orientativa · ${h(p.paper)}</span></div><div class="paper-stage">${documentPreview(c,entries,state.preview)}</div><div class="checks">${coverWarnings(c).map(w=>`<span class="warn">${h(w)}</span>`).join('')}${checks.map(check=>`<span class="${check.ok?'pass':'warn'}">${check.ok?'✓':'⚠'} ${h(check.text)}</span>`).join('')}<span class="warn">Revisá paginación, fuentes disponibles y tamaño final del PDF en el diálogo de impresión.</span><span class="warn">${c.reviewed?'Condiciones de participación: comprobación personal.':'Requisitos importados / de ejemplo: revisar contra las bases.'}</span></div><div class="actions" style="margin-top:20px"><button data-action="sent">Marcar como enviado y conservar copia</button></div></div></div>`;
}
function importDialog(){state.draft=null;showDialog('Traé un concurso a tu taller.',`<p class="muted">Abrí una convocatoria en Escritores.org y pegá su enlace individual.</p><form id="import-form"><label>URL del concurso<div class="import-box"><input type="url" name="url" required placeholder="https://www.escritores.org/recursos-para-escritores/…" aria-label="URL de Escritores.org"><button class="primary" type="submit">Extraer datos →</button></div></label><p id="import-status" class="hint" role="status">Extraemos la información disponible. Después podés completarla.</p></form><div class="form-foot"><a class="small" href="${WRITERS_LIST}" target="_blank" rel="noopener noreferrer">Buscar en Escritores.org ↗</a><button data-action="manual">Completar manualmente</button></div><p class="hint">Ejemplo real para probar: Dr. Alberto Manini Ríos 2026.</p><button class="quiet small" data-action="fill-url">Usar enlace de ese concurso</button>`);}
function extractionSummary(c){
  const pdfs=(c.pdfRead||[]).map(p=>`<p class="hint">${p.ok?'Texto del PDF leído.':'No se pudo leer el PDF.'} ${p.imagePages?'Contiene imágenes: puede haber requisitos que no se extrajeron.':''} <a href="${safeLink(p.url)}" target="_blank" rel="noopener noreferrer">Ver PDF ?</a></p>`).join('');
  const missing=c.detected?Object.entries({font:'fuente',size:'tamaño',paper:'hoja',lineSpacing:'interlineado'}).filter(([key])=>!c.detected[key]).map(([,label])=>label):[];
  return pdfs+(missing.length?`<p class="hint">No se detectaron: ${missing.join(', ')}. Los ajustes de exportación para esos campos son sugerencias editables.</p>`:'')+(c.plicaRequired===false?'<div class="notice warm">Las bases dicen que no admiten plica. Los datos personales se completan en el formulario del organizador.</div>':'');
}
function contestForm(draft,editing=false){
  state.draft={...draft,editing};const detected=key=>draft[key]?'<span class="field-source">Dato encontrado · revisar</span>':'<span class="field-help">No encontrado · podés completarlo</span>';
  showDialog(editing?'Revisar datos del concurso':'Revisá lo que encontramos.',`<div class="import-summary">${draft.extractedAt?'Consulta real a Escritores.org · '+new Date(draft.extractedAt).toLocaleString('es-UY'):'Ficha editable'}<br>Los requisitos y las condiciones necesitan revisión antes de participar.</div><form id="contest-form"><div class="form-grid"><label class="full">Nombre<input name="name" value="${h(draft.name||'')}" maxlength="250" required>${detected('name')}</label><label>Organiza<input name="organizer" value="${h(draft.organizer||'')}">${detected('organizer')}</label><label>País<input name="country" value="${h(draft.country||'')}"></label><label>Cierre de recepción<input type="date" name="deadline" value="${h(draft.deadline||'')}">${detected('deadline')}</label><label>Hora de cierre<input type="time" name="deadlineTime" value="${h(draft.deadlineTime||'')}"><span class="field-help">Dejar vacío si no se especifica.</span></label><label>Zona horaria<input name="timezone" value="${h(draft.timezone||'')}" placeholder="Ej.: Europe/Madrid"></label><label>Publicación prevista de resultados<input type="date" name="resultsDate" value="${h(draft.resultsDate||'')}">${detected('resultsDate')}</label><label class="full">Información sobre el fallo<input name="resultsNote" value="${h(draft.resultsNote||'')}" placeholder="Ej.: durante febrero, sin día exacto"></label><label class="full">Medio de entrega<input name="delivery" value="${h(draft.delivery||'')}" placeholder="Correo, formulario o papel"></label><label class="full">Requisitos detectados / notas<textarea name="rules" rows="5">${h(draft.rules||'')}</textarea><span class="field-help">La extracción es parcial. Leemos el texto de los PDF de Escritores.org; archivos escaneados o con imágenes pueden requerir revisión manual.</span></label><label>Máximo de poemas<input type="number" name="maxPoems" min="0" max="10000" value="${draft.maxPoems||0}"><span class="field-help">0 = sin límite configurado</span></label><label>Máximo de versos por poema<input type="number" name="maxVerses" min="0" max="100000" value="${draft.maxVerses||0}"></label><label>Mínimo de versos del conjunto<input type="number" name="minTotal" min="0" max="100000" value="${draft.minTotal||0}"></label><label>Máximo de versos del conjunto<input type="number" name="maxTotal" min="0" max="100000" value="${draft.maxTotal||0}"></label><label class="full">Enlace original / bases<input type="url" name="originalUrl" value="${h(draft.originalUrl||'')}"></label><label class="full">URL de Escritores.org<input type="url" name="sourceUrl" value="${h(draft.sourceUrl||'')}"></label><label class="check full"><input type="checkbox" name="reviewed" ${draft.reviewed?'checked':''}>Ya comprobé estos datos con las bases</label><p class="review-help">Esta marca indica que vos ya abriste las bases y comprobaste los datos importados. Es opcional, no impide guardar ni confirma automáticamente que puedas participar.</p></div>${draft.attachments?.length?`<p class="hint">Documentos enlazados: ${draft.attachments.map(a=>`<a href="${safeLink(a.url)}" target="_blank" rel="noopener noreferrer">${h(a.label||'PDF')} ↗</a>`).join(' · ')}</p>`:''}<div class="form-foot"><span class="small muted">Podés guardar y seguir revisando después.</span><button type="submit" class="primary">${editing?'Guardar cambios':'Guardar concurso'} →</button></div></form>`,true);
}
function tagDialog(ids){
  const poems=allPoems().filter(p=>ids.includes(p.id));if(!poems.length)return;const tags=tagCatalog(state.data,allPoems());
  showDialog(ids.length>1?'Etiquetar poemas seleccionados':'Etiquetas de '+poems[0].title,`<form id="tags-form" data-ids="${h(JSON.stringify(ids))}">${ids.length>1?'<label>Acción<select name="mode"><option value="add">Agregar las etiquetas marcadas</option><option value="remove">Quitar las etiquetas marcadas</option></select></label>':''}<fieldset class="tag-picker"><legend>Elegí las etiquetas</legend>${tags.map(tag=>`<label class="check"><input type="checkbox" name="tags" value="${h(tag)}" ${ids.length===1&&poems[0].tags.includes(tag)?'checked':''}>${tagMarkup(state.data,tag)}</label>`).join('')||'<p class="muted">Primero creá una etiqueta desde «Gestionar etiquetas».</p>'}</fieldset><p class="hint">Las etiquetas pertenecen al poema y se comparten entre sus versiones.</p><div class="form-foot"><button type="button" data-action="manage-tags">Crear o gestionar etiquetas</button><button class="primary" type="submit">Aplicar etiquetas</button></div></form>`);
}
function manageTagsDialog(){const tags=tagCatalog(state.data,allPoems());showDialog('Mis etiquetas',`<form id="create-tag-form"><label>Nueva etiqueta<input name="name" maxlength="60" required placeholder="Ej.: listo para concurso"></label><label class="tag-create-color">Color<input type="color" name="color" value="#3d7164"></label><div class="form-foot"><span class="small muted">Creala ahora y asignala después a tus poemas.</span><button type="submit" class="primary">Crear etiqueta</button></div></form><div class="tag-catalog">${tags.map(tag=>`<div>${tagMarkup(state.data,tag)}<input type="color" data-tag-color="${h(tag)}" value="${tagColor(state.data,tag)}" aria-label="Color de ${h(tag)}" title="Cambiar color de ${h(tag)}"><span class="small muted">${allPoems().filter(p=>p.tags.includes(tag)).length} ${allPoems().filter(p=>p.tags.includes(tag)).length===1?'poema':'poemas'}</span><button class="quiet small" data-action="delete-tag" data-tag="${h(tag)}" aria-label="Eliminar etiqueta ${h(tag)}">Eliminar</button></div>`).join('')||'<p class="muted">Todavía no creaste etiquetas.</p>'}</div>${tags.length?`<form id="rename-tag-form"><div class="form-grid"><label>Etiqueta a renombrar<select name="old">${tags.map(t=>`<option>${h(t)}</option>`).join('')}</select></label><label>Nuevo nombre<input name="next" required maxlength="60"></label></div><p class="hint">Se actualiza en todos los poemas. Si el nombre ya existe, las etiquetas se unifican.</p><div class="form-foot"><button type="button" data-action="close">Cerrar</button><button type="submit">Renombrar etiqueta</button></div></form>`:'<button data-action="close">Cerrar</button>'}`);}
function openEditor(poem,versionId='latest'){
  state.view='editor';state.pendingOpen={type:'workshop:open',sourceId:poem?.id||'',poemKey:poem?.sourceKey||'',title:poem?.title||'',font:poem?.font,color:poem?.color||state.library.settings.colors?.[poem?.title]||'#205EA6',versionId,text:poem?(versionId==='latest'?latestVersion(poem):poem.versions.find(v=>v.id===versionId)||latestVersion(poem)).poemText:''};render();
  if(state.editorReady){document.querySelector('#workshop-editor').contentWindow.postMessage(state.pendingOpen,location.origin);state.pendingOpen=null;}
}
function prepared(c){return {preparedAt:new Date().toISOString(),profile:structuredClone(c.profile),entries:selectedEntries(c).map(e=>({poem:{id:e.poem.id,title:e.poem.title},version:structuredClone(e.version)}))};}
function sentDialog(){const c=currentContest(),copy=c.lastPrepared||prepared(c);if(!copy.entries.length){toast('Seleccioná al menos un poema antes de marcar la entrega.');return;}showDialog('Conservar la entrega enviada',`<p class="muted">Confirmá que estas son las versiones que entregaste. Esta copia permanecerá igual aunque sigas editando.</p><div class="panel">${copy.entries.map(e=>`<div class="timeline-item"><strong>${h(e.poem.title)}</strong><p>${h(e.version.label||'Versión')} · ${countLines(e.version.poemText).verses} versos</p></div>`).join('')}</div><p class="hint">${c.lastPrepared?'Usaremos la última preparación descargada o abierta para impresión.':'Todavía no exportaste: conservaremos la selección actual.'}</p><div class="form-foot"><button data-action="close">Volver</button><button class="primary" data-action="confirm-sent">Confirmar envío y guardar copia</button></div>`);}
async function plicaDialog(){
  const c=currentContest();showDialog('Datos de la plica', '<p class="muted">Cargando datos guardados en la base local…</p>');
  try{const response=await fetch('/api/plicas');const result=await response.json();if(!response.ok)throw Error(result.error||'No se pudo cargar la plica.');if(!modal.open)return;
    state.plicaDraft=result.plica||{};const p=state.plicaDraft;
    showDialog('Datos de la plica',`<p class="muted">Estos datos pertenecen a tu perfil y se reutilizan en todos los concursos. Los datos personales se guardan cifrados. Revisá la declaración y su fecha antes de cada entrega.</p>${c.plicaRequired===false?'<div class="notice warm">Las bases detectadas dicen que no admiten plica. Usá estos datos para completar el formulario del organizador.</div>':''}${c.aiPlacement==='obra'?'<div class="notice warm">Este concurso pide la declaración de IA en la primera página de la obra. Incluirla en la plica no reemplaza ese requisito.</div>':''}<form id="plica-form"><div class="form-grid">${[['fullName','Nombre completo'],['identityDocument','Documento de identidad'],['postalAddress','Dirección postal'],['email','Correo electrónico'],['phone','Teléfono']].map(([key,label])=>`<label class="${key==='postalAddress'?'full':''}">${label}<input name="${key}" value="${h(p[key]||'')}"></label>`).join('')}<label class="full">Reseña biobibliográfica<textarea name="biography" rows="3">${h(p.biography||'')}</textarea></label><label class="check full"><input type="checkbox" name="includeAi" ${p.includeAi?'checked':''}>Incluir declaración sobre inteligencia artificial</label><label class="full">Texto de la declaración<textarea name="aiStatement" rows="4">${h(p.aiStatement||DEFAULT_AI_STATEMENT)}</textarea><span class="field-help">Texto sugerido, editable. Incluilo solo si describe tu caso y cumple las bases. El texto exacto que pide el concurso tiene prioridad.</span></label><label>Nombre para la firma<input name="signatureName" value="${h(p.signatureName||'')}"></label><label>Fecha de la declaración<input type="date" name="signatureDate" value="${h(p.signatureDate||'')}"></label></div><p class="hint">Guardar no firma el documento. Si las bases lo exigen, firmá la declaración antes de entregarla.</p><p id="plica-status" class="hint" role="status"></p><div class="form-foot"><button data-action="close" type="button">Cancelar</button><div class="actions"><button type="submit" name="operation" value="save">Guardar datos</button><button class="primary" type="submit" name="operation" value="download">Guardar y descargar DOCX</button></div></div></form>`);
  }catch(e){showDialog('No pudimos cargar la plica',`<p class="error">${h(e.message)}</p><button data-action="close">Cerrar</button>`);}
}
async function importUrl(url,editing=false){
  const button=modal.querySelector('button[type=submit]'),status=modal.querySelector('#import-status');if(button)button.disabled=true;if(status)status.textContent='Consultando la convocatoria…';
  try{const response=await fetch('/api/prototype/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url})});const result=await response.json();if(!response.ok)throw Error(result.error||'No se pudo extraer.');const existing=editing?currentContest():null;if(existing){const fields=['name','organizer','country','deadline','deadlineTime','timezone','resultsDate','resultsNote','delivery','rules','originalUrl','extractedAt','attachments','pdfRead','plicaRequired','aiRequirement','aiPlacement','coverRequirements','maxPoems','maxVerses','minTotal','maxTotal','minPoemVerses','verseCounting'];const draft={...existing,reviewed:false,demo:false};for(const key of fields)if(result.contest[key] || result.contest[key]===false)draft[key]=result.contest[key];contestForm(draft,true);}else contestForm({...result.contest,demo:false});}catch(error){if(status){status.textContent=error.message;status.classList.add('error');}else toast(error.message);}finally{if(button)button.disabled=false;}
}
document.addEventListener('click',async event=>{
  const lib=event.target.closest('[data-lib]');if(lib){await library.click(lib);return;}
  const view=event.target.closest('[data-view]');if(view){state.view=view.dataset.view;render();return;}
  const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;
  if(action==='close'){modal.close();return;}
  if(action==='enable-notifications'){try{await reminderNotifications.enable();toast(reminderNotifications.status().enabled?'Avisos activados en este navegador.':'No se activaron los avisos. Podés seguir consultándolos aquí.');}catch(e){toast(e.message);}renderReminders();return;}
  if(action==='disable-notifications'){reminderNotifications.disable();renderReminders();toast('Avisos del navegador desactivados.');return;}
  if(action==='import'){importDialog();return;}
  if(action==='fill-url'){modal.querySelector('[name=url]').value=state.data.contests.find(c=>c.id==='manini')?.sourceUrl||seedData().contests[0].sourceUrl;return;}
  if(action==='manual'){contestForm({profile:structuredClone(seedData().contests[1].profile)});return;}
  if(action==='filter-tag'){state.tags=state.tags.includes(button.dataset.tag)?state.tags.filter(t=>t!==button.dataset.tag):[...state.tags,button.dataset.tag];renderLibrary();return;}
  if(action==='clear-tags'){state.tags=[];renderLibrary();return;}
  if(action==='edit-tags'){tagDialog([button.dataset.id]);return;}
  if(action==='bulk-tags'){tagDialog(state.checked);return;}
  if(action==='manage-tags'){manageTagsDialog();return;}
  if(action==='delete-tag'){state.data.tagCatalog=tagCatalog(state.data,allPoems());updateTagEverywhere(state.data,button.dataset.tag);state.tags=state.tags.filter(t=>t!==button.dataset.tag);if(persist()){manageTagsDialog();render();toast('Etiqueta eliminada de la biblioteca.');}return;}
  if(action==='open-contest-poem'){const p=allPoems().find(p=>p.id===button.dataset.id),selection=currentContest()?.selections.find(s=>s.poemId===p?.id);openEditor(p,selection?.versionId||'latest');return;}
  if(action==='edit-poem'){openEditor(allPoems().find(p=>p.id===button.dataset.id));return;}
  if(action==='new-poem'){openEditor();return;}
  if(action==='open-contest'){state.contestId=button.dataset.id;state.view='detail';render();window.scrollTo(0,0);return;}
  const c=currentContest();
  if(action==='toggle-agenda'){const target=state.data.contests.find(c=>c.id===(button.dataset.id||state.contestId));if(!target)return;target.agendaEnabled=target.agendaEnabled===false;if(persist()){render();toast(target.agendaEnabled?'Concurso agregado a la agenda. Avisos activos.':'Concurso fuera de la agenda. Sus avisos quedan pausados.');}return;}
  if(action==='delete-contest'){const target=state.data.contests.find(c=>c.id===(button.dataset.id||state.contestId));if(!target)return;showDialog('Eliminar concurso',`<p>Se eliminará <strong>${h(target.name)}</strong>, su configuración y sus copias de entregas.</p><p>Los poemas de Biblioteca y tus datos personales de la plica se conservan.</p><div class="form-foot"><button data-action="close">Cancelar</button><button class="primary" data-action="confirm-delete-contest" data-id="${h(target.id)}">Eliminar concurso</button></div>`);return;}
  if(action==='confirm-delete-contest'){const id=button.dataset.id;state.data.contests=state.data.contests.filter(c=>c.id!==id);if(persist()){modal.close();state.view='contests';state.contestId='';render();toast('Concurso eliminado. Tus poemas y tus datos de plica se conservan.');}return;}
  if(action==='edit-contest'){contestForm(c,true);return;}
  if(action==='refresh'){showDialog('Volver a consultar la convocatoria',`<p class="muted">Consultaremos la página de Escritores.org. Podrás revisar los datos nuevos antes de guardarlos; se conservarán tus poemas, entregas y ajustes de exportación.</p><form id="refresh-form"><p id="import-status" class="hint" role="status"></p><div class="form-foot"><button type="button" data-action="close">Cancelar</button><button type="submit" class="primary">Consultar de nuevo</button></div></form>`);return;}
  if(action==='prepare'){state.view='export';state.preview='poem';render();window.scrollTo(0,0);return;}
  if(action==='preview-cover'||action==='preview-poem'){state.preview=action==='preview-cover'?'cover':'poem';renderExport();return;}
  if(action==='calendar'||action==='results-calendar'){const contest=button.dataset.id?state.data.contests.find(c=>c.id===button.dataset.id):c;try{downloadFile(safeName(contest.name)+'.ics',calendarText(contest,action==='calendar'?'deadline':'results'),'text/calendar;charset=utf-8');toast('Evento descargado. Abrilo con tu calendario para activar sus recordatorios.');}catch(e){toast(e.message);}return;}
  if(action==='docx'||action==='pdf'){
    const entries=selectedEntries(c);if(!entries.length)return;
    if(resolveSelection(allPoems(),c.selections).some(e=>!e.version)){toast('Hay una versión seleccionada que ya no está disponible. Revisá la selección.');return;}
    try{if(action==='docx')downloadFile(safeName(c.profile.workTitle||c.name)+'-OBRA.docx',buildDocx(c,entries));else printDocument(c,entries);c.lastPrepared=prepared(c);persist();toast(action==='docx'?'DOCX descargado. Conservamos esta preparación para registrar el envío.':'Se abrió la impresión. Elegí Guardar como PDF y revisá la paginación.');}catch(e){toast(e.message);}return;
  }
  if(action==='plica'){await plicaDialog();return;}
  if(action==='sent'){sentDialog();return;}
  if(action==='confirm-sent'){const copy=c.lastPrepared||prepared(c);c.snapshots.push({...structuredClone(copy),sentAt:new Date().toISOString()});c.status='sent';persist();modal.close();state.view='detail';render();toast('Entrega registrada. La copia enviada quedó conservada.');return;}
  if(action==='snapshot'){const s=c.snapshots[Number(button.dataset.index)];showDialog('Copia de la entrega enviada',`<p class="small muted">${new Date(s.sentAt).toLocaleString('es-UY')} · ${h(s.profile.font)} ${s.profile.size} pt · ${h(s.profile.paper)}</p>${s.entries.map(e=>`<h3>${h(e.poem.title)} · ${h(e.version.label)}</h3><div class="snapshot">${h(e.version.poemText)}</div>`).join('')}<div class="form-foot"><span class="small muted">Esta copia no sigue las nuevas versiones.</span><button data-action="download-snapshot" data-index="${button.dataset.index}">Descargar copia DOCX</button></div>`);return;}
  if(action==='download-snapshot'){const s=c.snapshots[Number(button.dataset.index)];downloadFile(safeName(s.profile.workTitle||c.name)+'-ENTREGADO.docx',buildDocx({...c,profile:s.profile},s.entries));return;}
  if(action==='results'){showDialog('Registrar resultados publicados',`<p class="muted">Abrí la publicación del organizador y guardá su enlace cuando hayas comprobado que contiene los resultados de esta edición.</p><form id="results-form"><label>Enlace a los resultados<input type="url" name="url" required value="${h(c.resultsUrl||'')}" placeholder="https://…"></label><label class="check" style="margin-top:17px"><input type="checkbox" required>Comprobé que se publicaron los resultados de este concurso</label><p class="hint">No detectamos automáticamente nuevas publicaciones en este prototipo.</p><div class="form-foot"><button data-action="close" type="button">Cancelar</button><button class="primary" type="submit">Guardar publicación</button></div></form>`);return;}
});
document.addEventListener('input',event=>{if(event.target.closest('#create-tag-form')&&event.target.name==='name'){const color=event.target.form.elements.color;if(color.dataset.manual!=='true')color.value=tagColor(state.data,event.target.value);} if(event.target.id==='poem-search'){state.query=event.target.value;const position=event.target.selectionStart;renderLibrary();const field=document.querySelector('#poem-search');field.focus();field.setSelectionRange(position,position);}});
document.addEventListener('change',async event=>{
  const e=event.target;if(e.hasAttribute('data-tag-color')){setTagColor(state.data,e.dataset.tagColor,e.value);if(persist()){manageTagsDialog();render();}return;}if(e.closest('#create-tag-form')&&e.name==='color')e.dataset.manual='true';if(await library.change(e))return;
  if(e.id==='tag-mode'){state.tagMode=e.value;renderLibrary();return;}
  if(e.dataset.checkPoem){state.checked=e.checked?[...new Set([...state.checked,e.dataset.checkPoem])]:state.checked.filter(id=>id!==e.dataset.checkPoem);renderLibrary();return;}
  const c=currentContest();
  if(e.dataset.associate){c.selections=e.checked?[...c.selections,{poemId:e.dataset.associate,versionId:'latest'}]:c.selections.filter(s=>s.poemId!==e.dataset.associate);persist();renderDetail();return;}
  if(e.dataset.versionPoem){c.selections.find(s=>s.poemId===e.dataset.versionPoem).versionId=e.value;persist();renderDetail();return;}
  if(e.dataset.reminder){const n=Number(e.dataset.reminder);c.reminders=e.checked?[...new Set([...c.reminders,n])]:c.reminders.filter(d=>d!==n);persist();return;}
  if(e.id==='contest-status'){if(e.value==='sent'&&c.status!=='sent'){e.value=c.status;sentDialog();return;}c.status=e.value;persist();renderDetail();return;}
  if(e.dataset.profile){const key=e.dataset.profile;let value=e.type==='checkbox'?e.checked:['size','margin','lineSpacing'].includes(key)?Number(e.value):e.value;if(key==='size')value=Math.min(24,Math.max(8,value||12));if(key==='margin')value=Math.min(5,Math.max(1,value||2.5));c.profile[key]=value;if(key==='cover'&&!value)state.preview='poem';persist();renderExport();}
});
document.addEventListener('submit',async event=>{
  const form=event.target;if(form.id.startsWith('library-')){event.preventDefault();await library.submit(form);return;}if(!['import-form','refresh-form','contest-form','tags-form','create-tag-form','rename-tag-form','plica-form','results-form'].includes(form.id))return;event.preventDefault();const data=new FormData(form);
  if(form.id==='import-form'){await importUrl(data.get('url'));return;}
  if(form.id==='refresh-form'){await importUrl(currentContest().sourceUrl,true);return;}
  if(form.id==='contest-form'){
    const next={...state.draft};delete next.editing;
    for(const name of ['name','organizer','country','deadline','deadlineTime','timezone','resultsDate','resultsNote','delivery','rules','originalUrl','sourceUrl'])next[name]=String(data.get(name)||'').trim();
    for(const name of ['maxPoems','maxVerses','minTotal','maxTotal'])next[name]=Number(data.get(name))||0;
    next.reviewed=data.has('reviewed');if(!next.name){toast('Escribí un nombre para el concurso.');return;}
    if(next.maxTotal&&next.maxTotal<next.minTotal){toast('El máximo de versos debe ser igual o mayor al mínimo.');return;}
    const existing=state.data.contests.find(c=>c.id===next.id)||state.data.contests.find(c=>next.sourceUrl&&c.sourceUrl===next.sourceUrl);
    if(existing){const protectedFields={id:existing.id,selections:existing.selections,snapshots:existing.snapshots,status:existing.status,lastPrepared:existing.lastPrepared,profile:existing.profile,reminders:existing.reminders,agendaEnabled:existing.agendaEnabled};Object.assign(existing,next,protectedFields);state.contestId=existing.id;}else{next.id=crypto.randomUUID();next.status='interested';next.selections=[];next.snapshots=[];next.reminders=[14,7,2];next.agendaEnabled=true;next.profile??=structuredClone(seedData().contests[1].profile);next.demo=false;state.data.contests.push(next);state.contestId=next.id;}
    if(persist()){modal.close();state.view='detail';render();if(!existing){try{await reminderNotifications.enable();}catch(error){toast(error.message);return;}toast(reminderNotifications.status().enabled?'Concurso guardado con avisos activados.':'Concurso guardado en la agenda. Para los avisos del navegador necesitás permitir las notificaciones.');}else toast('Datos actualizados. Se conservaron tus selecciones y entregas.');}return;
  }
  if(form.id==='create-tag-form'){try{createTag(state.data,data.get('name'),allPoems(),data.get('color'));if(persist()){manageTagsDialog();render();toast('Etiqueta creada. Ya podés asignarla a tus poemas.');}}catch(e){toast(e.message);}return;}
  if(form.id==='tags-form'){const ids=JSON.parse(form.dataset.ids),tags=data.getAll('tags').filter(t=>tagCatalog(state.data,allPoems()).includes(t));for(const id of ids){const poem=state.data.poems.find(p=>p.id===id),current=poem?.tags||state.data.localTags[id]||[],next=ids.length===1?tags:data.get('mode')==='remove'?current.filter(t=>!tags.includes(t)):[...new Set([...current,...tags])];if(poem)poem.tags=next;else state.data.localTags[id]=next;}if(persist()){modal.close();render();toast('Etiquetas aplicadas.');}return;}
  if(form.id==='rename-tag-form'){const old=String(data.get('old')),next=tagsFromText(data.get('next'));if(next.length!==1||next[0].length>60){toast('Escribí un único nombre de etiqueta de hasta 60 caracteres.');return;}state.data.tagCatalog=tagCatalog(state.data,allPoems());updateTagEverywhere(state.data,old,next[0]);state.tags=[...new Set(state.tags.map(t=>t===old?next[0]:t))];if(persist()){modal.close();render();toast('Etiqueta renombrada en todos los poemas.');}return;}
  if(form.id==='plica-form'){
    const c=currentContest(),plica=Object.fromEntries(data.entries());plica.includeAi=data.has('includeAi');delete plica.operation;
    const status=form.querySelector('#plica-status');const buttons=[...form.querySelectorAll('button[type=submit]')];buttons.forEach(b=>b.disabled=true);
    try{const response=await fetch('/api/plicas',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({plica})});const result=await response.json();if(!response.ok)throw Error(result.error||'No se pudo guardar.');state.plicaDraft=result.plica;
      if(event.submitter?.value==='download'){downloadFile('PLICA-'+safeName(c.profile.pseudonym||'seudonimo')+'.docx',buildDocx(c,selectedEntries(c),true,plicaExportFields(result.plica)));modal.close();toast('Plica guardada en la base de datos y descargada.');}else {status.textContent='Datos guardados en la base de datos.';toast('Plica guardada. Podés retomarla después.');}
    }catch(e){status.textContent=e.message;status.classList.add('error');}finally{buttons.forEach(b=>b.disabled=false);}return;
  }
  if(form.id==='results-form'){const value=String(data.get('url'));if(!safeLink(value)){toast('Usá un enlace HTTP o HTTPS válido.');return;}currentContest().resultsUrl=value;currentContest().resultsConfirmedAt=new Date().toISOString();if(persist()){modal.close();render();toast('Resultados publicados: enlace confirmado y guardado.');}return;}
});
window.addEventListener('storage',e=>{if(e.key===LIBRARY_KEY||e.key===STORAGE_KEY){if(e.key===STORAGE_KEY)state.data=load();render();}});
modal.addEventListener('click',event=>{if(event.target!==modal)return;const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)modal.close();});
window.addEventListener('message',event=>{
  if(event.origin!==location.origin||event.source!==document.querySelector('#workshop-editor').contentWindow)return;
  const message=event.data;
  if(message?.type==='workshop:resize'){if(Number.isFinite(message.height)&&message.height>0)document.querySelector('#workshop-editor').style.height=Math.ceil(message.height)+'px';return;}
  if(message?.type==='workshop:theme'){state.editorTheme=message.color;document.documentElement.style.setProperty('--working-poem-ink',message.ink||'#fff');document.documentElement.style.setProperty('--color-surface',message.surface||'12%');applyEditorTheme();return;}
  if(message?.type==='workshop:library-result'){const pending=state.library.pending[message.requestId];if(pending){clearTimeout(pending.timeout);delete state.library.pending[message.requestId];if(message.ok){state.library.settings=message.settings||state.library.settings;pending.resolve(message);}else pending.reject(Error(message.error));}return;}
  if(message?.type==='workshop:ready'){state.editorReady=true;libraryCommand({action:'snapshot'}).then(()=>{if(state.view==='library')renderLibrary();}).catch(()=>{});if(state.pendingOpen){event.source.postMessage(state.pendingOpen,location.origin);state.pendingOpen=null;}else event.source.postMessage({type:'workshop:view',view:state.view},location.origin);}
  if(message?.type==='workshop:editor'){state.view='editor';render();}
  if(message?.type==='workshop:library'){state.view='library';state.library.tab='poems';const poem=allPoems().find(p=>p.sourceKey===message.poemKey);if(poem){state.library.poemId=poem.id;state.library.versionId='latest';}render();window.scrollTo(0,0);}
  if(message?.type==='workshop:saved'){const poem=state.data.poems.find(p=>p.id===message.sourceId);if(poem){poem.linkedLocalId='local:'+message.poemKey;persist();}document.querySelector('#poem-count').textContent=allPoems().length;}
  if(message?.type==='workshop:toast')toast(message.message);
  if(message?.type==='workshop:error')toast(message.message);
  if(message?.type==='workshop:library-changed' && !['editor','files'].includes(state.view))render();
});
window.addEventListener('focus',()=>{if(!modal.open)render();});
